import java.util.*;

public class WordFrequency {
    public static Map<String, Integer> count(List<String> words) {
        Map<String, Integer> counts = new HashMap<>();
        for (String word : words) {
            counts.merge(word, 1, Integer::sum);
        }
        return counts;
    }
}

import java.util.*;

public class FizzBuzz {
    public static List<String> fizzBuzz(int n) {
        List<String> result = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (i % 15 == 0) result.add("FizzBuzz");
            else if (i % 3 == 0) result.add("Fizz");
            else if (i % 5 == 0) result.add("Buzz");
            else result.add(String.valueOf(i));
        }
        return result;
    }
}

public class Palindrome {
    public static boolean isPalindrome(String s) {
        if (s == null) return false;
        String lower = s.toLowerCase();
        int left = 0, right = lower.length() - 1;
        while (left < right) {
            if (lower.charAt(left) != lower.charAt(right)) return false;
            left++;
            right--;
        }
        return true;
    }
}

import java.util.*;
import java.util.stream.*;

public class GroupByLength {
    public static Map<Integer, List<String>> group(List<String> words) {
        return words.stream()
            .collect(Collectors.groupingBy(String::length));
    }
}

import java.util.*;
import java.util.stream.*;

public class Deduplicate {
    public static List<Integer> dedupe(List<Integer> input) {
        return input.stream().distinct().collect(Collectors.toList());
    }
}

public class BankAccount {
    private double balance;

    public BankAccount(double initialBalance) {
        if (initialBalance < 0) throw new IllegalArgumentException("Initial balance cannot be negative");
        this.balance = initialBalance;
    }

    public void deposit(double amount) {
        if (amount < 0) throw new IllegalArgumentException("Deposit cannot be negative");
        balance += amount;
    }

    public void withdraw(double amount) {
        if (amount < 0) throw new IllegalArgumentException("Withdrawal cannot be negative");
        if (amount > balance) throw new IllegalArgumentException("Insufficient funds");
        balance -= amount;
    }

    public double getBalance() {
        return balance;
    }
}

